@testable import Zoomies

final class WorkflowImagePersistenceLogicTests: XCTestCase {
    func testEncodedImageDataConvertsNonPngExtensionToUniquePngURL() throws {
        let image = TestSupport.solidImage(width: 80, height: 40, color: .systemRed)
        let originalURL = URL(fileURLWithPath: "/tmp/example.heic")

        let encoded = try XCTUnwrap(
            WorkflowImagePersistenceLogic.encodedImageData(
                from: image,
                originalURL: originalURL,
                uniqueURL: { proposedName, directory in
                    XCTAssertEqual(proposedName, "example.png")
                    return directory.appendingPathComponent("example_2.png")
                }
            )
        )

        XCTAssertFalse(encoded.data.isEmpty)
        XCTAssertEqual(encoded.outputURL.lastPathComponent, "example_2.png")
    }

    func testEncodedImageDataEmbedsRoundTripMetadataForPNG() throws {
        let image = TestSupport.solidImage(width: 60, height: 30, color: .systemRed)
        let original = try TestSupport.solidImagePNGData(width: 40, height: 20, color: .systemBlue)

        let encoded = try XCTUnwrap(
            WorkflowImagePersistenceLogic.encodedImageData(
                from: image,
                originalURL: URL(fileURLWithPath: "/tmp/example.png"),
                cleanOriginalPNG: original,
                prompt: "embed me",
                uniqueURL: { name, directory in directory.appendingPathComponent(name) }
            )
        )

        let extracted = try XCTUnwrap(PNGMetadata.extract(fromPNG: encoded.data))
        XCTAssertEqual(extracted.prompt, "embed me")
        XCTAssertEqual(extracted.originalPNG, original)
    }

    func testEncodedImageDataEmbedsEditorStateWithoutPrompt() throws {
        let image = TestSupport.solidImage(width: 60, height: 30, color: .systemRed)
        let base = try TestSupport.solidImagePNGData(width: 40, height: 20, color: .systemBlue)
        let state = EditorCanvasState(
            baseImagePNG: base,
            items: [.arrow(start: .init(NSPoint(x: 1, y: 2)),
                           end: .init(NSPoint(x: 20, y: 10)),
                           color: .init(.systemRed),
                           lineWidth: 4)]
        )

        let encoded = try XCTUnwrap(
            WorkflowImagePersistenceLogic.encodedImageData(
                from: image,
                originalURL: URL(fileURLWithPath: "/tmp/example.png"),
                editorState: state,
                uniqueURL: { name, directory in directory.appendingPathComponent(name) }
            )
        )

        let extracted = try XCTUnwrap(PNGMetadata.extractEditorState(fromPNG: encoded.data))
        XCTAssertEqual(extracted.baseImagePNG, base)
        XCTAssertEqual(extracted.items, state.items)
    }

    func testEncodedImageDataEmbedsPromptAndEditorStateTogether() throws {
        let image = TestSupport.solidImage(width: 60, height: 30, color: .systemRed)
        let original = try TestSupport.solidImagePNGData(width: 40, height: 20, color: .systemBlue)
        let state = EditorCanvasState(
            baseImagePNG: original,
            items: [.text(.init(text: "label",
                                origin: .init(NSPoint(x: 8, y: 9)),
                                color: .init(.systemBlue),
                                fontSize: 18))]
        )

        let encoded = try XCTUnwrap(
            WorkflowImagePersistenceLogic.encodedImageData(
                from: image,
                originalURL: URL(fileURLWithPath: "/tmp/example.png"),
                cleanOriginalPNG: original,
                prompt: "embed me",
                editorState: state,
                uniqueURL: { name, directory in directory.appendingPathComponent(name) }
            )
        )

        let note = try XCTUnwrap(PNGMetadata.extract(fromPNG: encoded.data))
        let extractedState = try XCTUnwrap(PNGMetadata.extractEditorState(fromPNG: encoded.data))
        XCTAssertEqual(note.prompt, "embed me")
        XCTAssertEqual(note.originalPNG, original)
        XCTAssertEqual(extractedState.items, state.items)
    }

    func testEncodedImageDataSkipsEmbeddingWhenPromptEmpty() throws {
        let image = TestSupport.solidImage(width: 60, height: 30)
        let original = try TestSupport.solidImagePNGData(width: 40, height: 20)

        let encoded = try XCTUnwrap(
            WorkflowImagePersistenceLogic.encodedImageData(
                from: image,
                originalURL: URL(fileURLWithPath: "/tmp/example.png"),
                cleanOriginalPNG: original,
                prompt: "",
                uniqueURL: { name, directory in directory.appendingPathComponent(name) }
            )
        )

        XCTAssertNil(PNGMetadata.extract(fromPNG: encoded.data))
    }

    func testEncodedImageDataRewritesNonPNGInputToPNGAndEmbeds() throws {
        // PNG-only: a non-PNG input is rewritten to .png on save and still
        // carries the round-trip metadata.
        let image = TestSupport.solidImage(width: 60, height: 30)
        let original = try TestSupport.solidImagePNGData(width: 40, height: 20)

        let encoded = try XCTUnwrap(
            WorkflowImagePersistenceLogic.encodedImageData(
                from: image,
                originalURL: URL(fileURLWithPath: "/tmp/example.jpg"),
                cleanOriginalPNG: original,
                prompt: "embed me",
                uniqueURL: { name, directory in directory.appendingPathComponent(name) }
            )
        )

        XCTAssertEqual(encoded.outputURL.pathExtension, "png")
        XCTAssertTrue(PNGMetadata.isPNG(encoded.data))
        let extracted = try XCTUnwrap(PNGMetadata.extract(fromPNG: encoded.data))
        XCTAssertEqual(extracted.prompt, "embed me")
        XCTAssertEqual(extracted.originalPNG, original)
    }

    func testWriteEncodedImageDataRemovesOriginalWhenOutputMoves() throws {
        let root = try TestSupport.makeTemporaryDirectory()
        defer { TestSupport.removeIfExists(root) }

        let originalURL = root.appendingPathComponent("shot.heic")
        let outputURL = root.appendingPathComponent("shot.png")
        let fileManager = FileManager.default

        try Data("old".utf8).write(to: originalURL, options: .atomic)

        let finalURL = try WorkflowImagePersistenceLogic.writeEncodedImageData(
            Data("new".utf8),
            to: outputURL,
            originalURL: originalURL,
            fileManager: fileManager
        )

        XCTAssertEqual(finalURL, outputURL)
        XCTAssertTrue(fileManager.fileExists(atPath: outputURL.path))
        XCTAssertFalse(fileManager.fileExists(atPath: originalURL.path))
    }
}

import AppKit

enum RenamePanelAction {
    case save(newName: String)
    case copyAndSave(newName: String)
    case copyAndDelete(newName: String)
    case delete
    case close
    case goToNote(newName: String)
}

final class RenamePanelController: NSWindowController {
    var onAction: ((RenamePanelAction) -> Void)?

    private let textField = CommandAwareTextField()
    private let shortcutLabel = NSTextField(labelWithString: "")
    private var escapeKeyDeletesFile: Bool = true
    private var showsCopyAndDiscard: Bool = true

    private var originalBaseName: String = ""
    private var originalExtension: String = ""
    private var allowsNoteNavigation: Bool = true

    convenience init(initialFilename: String,
                     escapeKeyDeletesFile: Bool = true,
                     showsCopyAndDiscard: Bool = true,
                     allowsNoteNavigation: Bool = true) {
        let contentRect = NSRect(x: 0, y: 0, width: 410, height: 215)
        let panel = FloatingInputPanel(contentRect: contentRect)
        panel.titleVisibility = .hidden
        panel.titlebarAppearsTransparent = true

        self.init(window: panel)
        self.escapeKeyDeletesFile = escapeKeyDeletesFile
        self.showsCopyAndDiscard = showsCopyAndDiscard
        self.allowsNoteNavigation = allowsNoteNavigation
        configureFilenameMetadata(initialFilename: initialFilename)
        configureUI(initialFilename: initialFilename)
    }

    override init(window: NSWindow?) {
        super.init(window: window)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    private func configureFilenameMetadata(initialFilename: String) {
        let ns = initialFilename as NSString
        originalExtension = ns.pathExtension
        originalBaseName = ns.deletingPathExtension
    }

    private func configureUI(initialFilename: String) {
        guard let contentView = window?.contentView else { return }

        let container = MenuSurfaceMaterial.makeFillingView(frame: contentView.bounds)
        contentView.addSubview(container)

        let titleLabel = NSTextField(labelWithString: "Filename")
        titleLabel.font = NSFont.systemFont(ofSize: 13, weight: .medium)

        textField.stringValue = WorkflowFilenameLogic.editableFilename(initialFilename)
        textField.isBordered = true
        textField.focusRingType = .default
        textField.bezelStyle = .roundedBezel
        textField.font = NSFont.systemFont(ofSize: 13)
        textField.drawsBackground = true
        textField.backgroundColor = .textBackgroundColor
        textField.textColor = .textColor

        textField.keyCommandHandler = { [weak self] command in
            guard let self = self else {
                return
            }
            let rawValue = self.textField.stringValue
            let sanitized = self.sanitizedFilename(from: rawValue)
            self.textField.stringValue = WorkflowFilenameLogic.editableFilename(sanitized)

            switch command {
            case .enter:
                self.onAction?(.save(newName: self.textField.stringValue))
            case .commandEnter, .commandShiftEnter:
                self.onAction?(.copyAndSave(newName: self.textField.stringValue))
            case .commandBackspace:
                if self.showsCopyAndDiscard {
                    self.onAction?(.copyAndDelete(newName: self.textField.stringValue))
                }
            case .escape:
                if self.escapeKeyDeletesFile {
                    self.onAction?(.delete)
                } else {
                    self.onAction?(.close)
                }
            case .tab:
                if self.allowsNoteNavigation {
                    self.onAction?(.goToNote(newName: self.textField.stringValue))
                }
            case .shiftTab:
                break
            }
        }

        let escapeLabel = escapeKeyDeletesFile ? "Delete" : "Close"
        var shortcutParts = ["Enter: Save", "⌘↩: Copy+Save"]
        if showsCopyAndDiscard {
            shortcutParts.append("⌘⌫: Copy+Delete")
        }
        shortcutParts.append("Esc: \(escapeLabel)")
        if allowsNoteNavigation {
            shortcutParts.append("Tab: Note")
        }
        shortcutLabel.stringValue = shortcutParts.joined(separator: "    ")
        shortcutLabel.font = NSFont.systemFont(ofSize: 11)
        shortcutLabel.textColor = NSColor.secondaryLabelColor
        shortcutLabel.lineBreakMode = .byWordWrapping

        [titleLabel, textField, shortcutLabel].forEach { view in
            view.translatesAutoresizingMaskIntoConstraints = false
            container.addSubview(view)
        }

        NSLayoutConstraint.activate([
            titleLabel.topAnchor.constraint(equalTo: container.topAnchor, constant: 18),
            titleLabel.leadingAnchor.constraint(equalTo: container.leadingAnchor, constant: 20),

            textField.topAnchor.constraint(equalTo: titleLabel.bottomAnchor, constant: 8),
            textField.leadingAnchor.constraint(equalTo: container.leadingAnchor, constant: 20),
            textField.trailingAnchor.constraint(equalTo: container.trailingAnchor, constant: -20),

            shortcutLabel.topAnchor.constraint(equalTo: textField.bottomAnchor, constant: 12),
            shortcutLabel.leadingAnchor.constraint(equalTo: container.leadingAnchor, constant: 20),
            shortcutLabel.trailingAnchor.constraint(equalTo: container.trailingAnchor, constant: -20)
        ])

        window?.initialFirstResponder = textField
    }

    private func sanitizedFilename(from input: String) -> String {
        let fallbackBase = originalBaseName.isEmpty ? "Screenshot" : originalBaseName
        let fallbackName = originalExtension.isEmpty ? fallbackBase : "\(fallbackBase).\(originalExtension)"
        let fallbackURL = URL(fileURLWithPath: "/tmp/\(fallbackName)")
        return WorkflowFilenameLogic.sanitizeFilename(input, preservingExtensionOf: fallbackURL)
    }

    func show() {
        guard let window = window else {
            return
        }

